// Each guide follows the same editorial structure so a reader can scan the answer,
// work through the steps, and decide on a sensible next action without inflated claims.
const metaDescription = description => {
  const complete = `${description} Practical guidance for clear next steps, useful handoffs and people-first customer follow-up.`;
  return complete.length <= 160 ? complete : complete.slice(0, complete.lastIndexOf(' ', 160));
};

const guide = ({ slug, title, description, answer, focus, steps, checklist, faqs: guideFaqs, date, landing, related, metaTitle }) => ({
  slug, title, description, metaDescription: metaDescription(description), answer, focus, steps, checklist, faqs: guideFaqs, date, landing, related, metaTitle,
  closing: `Use this guide as a starting point, then test the process with the people who answer customers every day. Keep a note of where they need to search for information, copy details or wait for an answer; those are useful signals for the next improvement. ${focus} A small change that the team can follow consistently is more valuable than a large redesign that adds work or creates uncertainty. Write down the decision, the owner and the review date so the improvement does not get lost.\n\nBefore changing tools, agree what “better” means in practical terms. It might mean a clear owner for every open enquiry, less repeated data entry, fewer customers repeating their question, or a more reliable next step. Review the change after real use, listen to the team and customers, and adjust it when the workflow does not match reality. If you need an outside view, a free audit can help identify the first sensible improvement without assuming that every business needs the same system.`,
});

export const articles = [
  guide({
    slug: 'improve-lead-management', title: 'How can a small business improve lead management?',
    description: 'A practical guide to capturing, organising and following up customer enquiries without adding unnecessary complexity.',
    answer: 'Small businesses improve lead management by putting every enquiry in one visible process, assigning a clear owner and recording the next action. Start with a simple shared tracker or CRM, then improve the handoffs that repeatedly cause delays.',
    focus: 'Lead management is not primarily about software. It is the everyday habit of making sure a customer receives a useful reply and that the team can see what should happen next.',
    steps: [['List every place enquiries arrive', 'Write down every route a customer can use: web forms, phone calls, WhatsApp, email, social messages, walk-ins and referrals. Then decide where each route is recorded. The point is not to force customers into one channel; it is to stop important details living only in one person’s inbox or memory.\n\nFor each route, capture only the information the next person needs: name, contact method, what the customer asked for, when it arrived, its source and the next step. A short consistent record is more useful than a detailed form that nobody completes.'], ['Give every enquiry an owner and next action', 'An enquiry can be open, quoted, booked, won or not proceeding, but a status alone does not create a response. Add an owner and a dated next action, such as “reply with options today” or “call after site visit.” If the owner changes, update the record at the same time.\n\nThis avoids the common gap where everyone assumes somebody else replied. It also makes a manager’s check-in constructive: ask what is needed to move the next action forward, rather than simply asking for an update.'], ['Make the first response easy to send', 'Prepare short, truthful reply templates for the questions you receive most often. A template should acknowledge the request, state what information you need and make the next step clear. Keep room for a person to adjust the wording; customers notice when a reply ignores their question.\n\nSpeed matters less than relevance. If you cannot answer immediately, send a brief acknowledgement and a realistic time for the fuller reply. That keeps the conversation active without promising more than the team can deliver.'], ['Review the process every week', 'Set aside a short weekly review for new enquiries, quotes awaiting a decision and records with no next action. Look for patterns: a source that creates incomplete requests, a common question that belongs on the website, or an approval that holds replies up. Make one small improvement at a time.\n\nAs the team grows, a lightweight CRM can replace a shared sheet. The process should lead the tool choice, not the other way around.']],
    checklist: ['All enquiry sources are listed.', 'Every live enquiry has an owner.', 'Every record has a dated next action.', 'The team reviews stalled enquiries weekly.'],
    faqs: [['Do I need a CRM to manage leads?', 'Not on day one. A shared tracker can work when the volume and team are small, provided everyone uses it consistently. Move to a CRM when shared context, permissions, reminders or reporting become difficult to manage.'], ['What is the most important lead field?', 'The next action and its owner are usually more useful than a long list of optional fields. They show whether the customer is waiting and who is responsible.']],
    date: '2026-09-18', landing: ['/services/lead-management', 'Lead management services'], related: ['what-is-crm', 'how-to-follow-up-customer-enquiry'],
  }),
  guide({
    slug: 'website-vs-whatsapp', title: 'Should my business use a website and WhatsApp together?',
    description: 'How a clear website and a well-managed WhatsApp handoff can help customers ask better questions and get useful replies.',
    answer: 'A website and WhatsApp work well together when the website answers the first questions and WhatsApp makes the personal next step easy. The important part is a clear handoff and a way for the team to manage the conversation after the click.',
    focus: 'A website does not replace a conversation, and a chat link does not replace useful information. Each channel can do the job it is best suited to.',
    // FOUNDER: add real example from Gari Qatar here
    steps: [['Put the decision-making information on the page', 'Before adding a WhatsApp button, make the page useful on its own. Explain the service, who it is for, what is included, the likely next step and any information customers commonly need before they contact you. Clear information helps a visitor decide whether to enquire and reduces repetitive questions.\n\nAvoid burying the contact route behind a long page. A visitor should be able to see what you offer, why it is relevant and how to ask a question without searching through navigation.'], ['Use WhatsApp for the conversation that follows', 'A WhatsApp link is particularly helpful when a customer wants to clarify something, share a photo, arrange a visit or discuss a specific requirement. A pre-filled opening message can include the service or page name, so neither customer nor team has to recreate the context.\n\nKeep the prepared message short and optional. It should help someone begin, not put words in their mouth or suggest an outcome you cannot guarantee.'], ['Design the handoff deliberately', 'Test the journey on a phone: read the page, tap the button and look at the draft message. Then ask what happens on the business side. Who sees the message? Is there a backup when that person is busy? Where is a serious enquiry recorded? These operational details determine whether the handoff feels professional.\n\nUse a real example only if it explains an actual, verifiable workflow rather than claiming results.'], ['Learn from the questions customers ask', 'Review real questions regularly. If the same issue appears repeatedly, improve the page, add a small FAQ or create a better reply template. Do not remove the human conversation simply because a question is common; use the page to make that conversation more informed.\n\nA website can also help you see which service pages lead to enquiries. Treat that information as a prompt to improve clarity, rather than a reason to chase vanity metrics.']],
    checklist: ['Each service page explains the offer before the chat link.', 'The WhatsApp message includes useful context.', 'Someone owns the first reply.', 'Important conversations are recorded for follow-up.'],
    faqs: [['Can WhatsApp replace my website?', 'It can be a valuable contact channel, but it does not give customers a stable place to understand your business, compare services or find key information when your team is unavailable.'], ['What should a WhatsApp button say?', 'Use a specific action such as “Ask about this service on WhatsApp.” It tells visitors what will happen and is clearer than a vague “Click here.”']],
    date: '2026-08-27', landing: ['/services/whatsapp-systems', 'WhatsApp systems'], related: ['do-i-need-website-instagram-whatsapp', 'how-to-stop-missing-whatsapp-enquiries'],
  }),
  guide({ slug: 'what-is-crm', title: 'What is CRM and does my small business need one?', description: 'A plain-English guide to CRM, when it becomes useful and how to start without making the process heavier.', answer: 'A CRM is a shared system for customer details, conversations, sales stages and next actions. A small business usually needs one when important context is spread across people, spreadsheets and messages, or when follow-up depends on memory.', focus: 'The right CRM is the one the team will use. Start with the customer journey and a small number of fields before adding automation or reports.', steps: [['Map the customer journey first', 'Follow one real enquiry from first contact to a completed service or sale. Note where information is collected, where it is copied, who needs to see it and where a customer has to repeat themselves. This shows the gaps a CRM should solve.\n\nDo not start with a feature checklist. A long list of capabilities can make a system look impressive while leaving the everyday handoffs unchanged.'], ['Define the minimum record', 'For many teams, a useful first record contains a name, contact details, source, need, owner, status and next action. Add job, booking or product details only when they genuinely help the next person act. Clear field names and agreed definitions prevent duplicate or inconsistent records.\n\nDecide who is allowed to edit key information and when the record should be updated. A shared system only stays useful when the update is part of the work, not an optional task at the end of the day.'], ['Choose a simple workflow', 'Use a few stages that reflect real decisions, such as new, contacted, quote sent, booked and closed. Each stage should mean something observable. Avoid stages that overlap or require a meeting to interpret.\n\nTest the workflow with the people who answer customers. If they need a parallel spreadsheet or personal notes to do their job, simplify the CRM before adding more fields.'], ['Improve after real use', 'Review the first month with the team. Check incomplete records, overdue actions and questions that are still being asked twice. Adjust one part at a time and explain why the change helps.\n\nA CRM can later connect to forms, WhatsApp workflows or booking systems, but those connections should support a stable process. Automation does not fix unclear ownership.']], checklist: ['The team has agreed stages.', 'Each contact has an owner and next action.', 'The record contains only useful fields.', 'The workflow has been tested by daily users.'], faqs: [['Is a spreadsheet a CRM?', 'A spreadsheet can manage a simple list, but it becomes difficult when several people need permissions, reminders, conversation history or dependable reporting.'], ['How long does CRM setup take?', 'It depends on the workflow and information to move. A sensible first setup focuses on the core journey and is refined with real use rather than attempting to model every exception at once.']], date: '2026-07-15', landing: ['/services/crm-systems', 'CRM systems'], related: ['spreadsheet-vs-crm-small-business', 'improve-lead-management'] }),
  guide({ slug: 'automation-ideas-qatar', title: 'What simple automation can help a Qatar small business?', description: 'Practical, low-risk automation ideas for repetitive handoffs in a small or growing business.', answer: 'The best small-business automation starts with a repeatable task that has clear inputs, a predictable action and a person responsible for exceptions. For Qatar businesses, that often means connecting website enquiries, WhatsApp messages, bookings or internal notifications in the way the team already works.', focus: 'Automation should remove copying and chasing, not hide important decisions. Keep a person involved when a customer request needs judgement, confirmation or care.', steps: [['Choose one repeated handoff', 'Look for work that happens many times: copying a website enquiry into a tracker, telling a colleague about a new booking or reminding a customer about an appointment. Draw the current steps in plain language. If the team cannot explain the process clearly, improve the process before automating it.\n\nA focused first workflow gives you a manageable way to test the tools, ownership and exception handling without disrupting everything at once.'], ['Set clear inputs and outputs', 'Define exactly what starts the workflow, which information is required, who receives the result and what counts as a failure. For example, a form submission might create a lead record and notify the assigned person. It should not silently send an inaccurate quote or make a booking without confirmation.\n\nKeep the data you move to the minimum necessary. This makes the workflow easier to understand and reduces the chance of carrying outdated information between systems.'], ['Keep people in the loop', 'Automation can notify, draft, create tasks and route information. A person should review unusual requests, customer complaints, pricing questions, availability and anything involving sensitive information. Make the handoff obvious so customers and team members know when a human should take over.\n\nWrite a short fallback instruction: who checks an error, how the customer is updated and where the missing item is recorded. That is more valuable than a complicated workflow diagram nobody opens.'], ['Review usefulness after launch', 'Ask whether the workflow removes a real manual step, whether the right person sees the result and whether exceptions are handled promptly. Update it when the team’s process changes.\n\nUse measures that matter to the team, such as fewer duplicate entries or clearer ownership. Avoid treating the number of integrations as evidence that a workflow is useful.']], checklist: ['The current process is written down.', 'A named person owns exceptions.', 'The workflow moves only needed data.', 'There is a simple failure check.'], faqs: [['What should I automate first?', 'Start with a frequent, stable handoff that the team already understands, such as creating a follow-up task from a website enquiry.'], ['Can automation answer customers by itself?', 'It can handle approved, routine messages, but pricing, availability, exceptions and sensitive requests should have appropriate human oversight.']], date: '2026-06-10', landing: ['/services/business-automation', 'business automation'], related: ['improve-lead-management', 'ai-customer-enquiries'] }),
  guide({ slug: 'ai-customer-enquiries', title: 'How can AI help handle customer enquiries?', description: 'Practical ways to use AI for routine enquiry support while keeping customers and team members connected to a person.', answer: 'AI can help with approved repeat questions, basic information collection and routing an enquiry to the right person. It should work within clear boundaries, avoid guessing and give customers an easy way to reach a human when the request needs judgement.', focus: 'A useful AI assistant is a carefully limited support tool, not an unsupervised decision-maker. Its quality depends on the accuracy of the source information and the team’s review process.', steps: [['Choose a narrow first task', 'Begin with one task such as answering approved FAQs, gathering the details needed for a quote request or classifying an incoming enquiry. Narrow tasks are easier to test because the expected information, tone and handoff are clear.\n\nDo not ask an assistant to invent availability, policies, prices or technical advice. Give it only information you have reviewed and a clear instruction to hand over when it lacks an answer.'], ['Build the knowledge carefully', 'Use current, business-approved content: service descriptions, operating hours, terms, FAQs and contact routes. Review this material before it is used, because an assistant can only be as reliable as the information it is given.\n\nSet a regular owner for updates. When a service, price range or policy changes, the assistant’s source material needs the same attention as the website.'], ['Design a human handoff', 'Make it easy for a customer to ask for a person. The assistant should recognise unclear, sensitive or unusual requests and pass along the conversation context so the customer does not have to start again.\n\nKeep human review for actions that affect commitments, personal information, bookings, pricing or availability. A handoff is a service feature, not a sign that the system failed.'], ['Review real interactions', 'Read a sample of conversations for accuracy, tone and useful escalation. Note where the assistant gives an incomplete answer or asks an unnecessary question, then improve the source material or instructions.\n\nTell customers when they are using an automated assistant and how to contact a person. Clear expectations help people choose the right route for their situation.']], checklist: ['The first task is narrow and documented.', 'Source information is reviewed and current.', 'A person can take over easily.', 'Interactions are reviewed regularly.'], faqs: [['Can AI replace customer service staff?', 'For most small businesses, AI is better used to assist with repeatable first steps while people handle judgement, relationships and exceptions.'], ['What happens if AI does not know the answer?', 'It should say so plainly and route the customer to a person or a reliable contact path rather than guessing.']], date: '2026-05-22', landing: ['/services/ai-solutions', 'AI solutions'], related: ['automation-ideas-qatar', 'how-to-follow-up-customer-enquiry'] }),
  // FOUNDER: add real example from Gari Qatar here
  guide({ slug: 'how-to-stop-missing-whatsapp-enquiries', title: 'How do I stop missing customer enquiries on WhatsApp?', description: 'A step-by-step way to make WhatsApp enquiries visible, owned and easier to follow up.', answer: 'Stop missing WhatsApp enquiries by making one person or team responsible for the inbox, recording serious requests in a shared process and scheduling a clear next action. The goal is not to reply to every message instantly; it is to ensure no customer is left without a useful response or a visible follow-up.', focus: 'WhatsApp is convenient for customers, but it can become difficult to manage when messages arrive across personal phones, busy group chats and shifting shifts.', steps: [['Create one monitored entry point', 'Decide which number or inbox receives business enquiries and who checks it during working hours. Make the contact route consistent on your website, social profiles and printed material. If more than one person replies, agree how they identify themselves and how they avoid answering the same question twice.\n\nSet realistic expectations for response times. An automatic acknowledgement can confirm that the message was received, but it should not claim that a reply is immediate unless the team can keep that promise.'], ['Separate conversation from follow-up', 'A chat thread is not a reliable task list. When an enquiry needs a quote, call, booking or later reply, add it to a shared tracker or CRM with an owner and date. Link or summarise the important context so the next person can understand the request without searching through a long conversation.\n\nUse simple labels or statuses consistently. They should help the team see what is new, what needs a response and what is waiting on the customer.'], ['Use useful quick replies', 'Prepare short replies for common first questions, including a greeting, what information is needed and the next step. Personalise the response where possible and avoid sending a generic script that does not address the message.\n\nQuick replies save typing, not responsibility. Check that the message is accurate and suitable before sending it, particularly when price, stock, timing or service scope is involved.'], ['Review open chats and missed calls', 'At the end of a shift or day, check new conversations, chats waiting for a reply and calls that need a return message. A short handover between team members can prevent enquiries from disappearing when somebody is off.\n\nUse a genuine example only when it explains an actual, verifiable workflow rather than claiming results.']], checklist: ['A business inbox has a named owner.', 'Serious enquiries enter a shared follow-up list.', 'Quick replies are reviewed and accurate.', 'Open conversations are checked at handover.'], faqs: [['Should I use my personal WhatsApp number?', 'A dedicated business contact route is usually easier to share, monitor and hand over. Choose a setup that matches your team size and customer expectations.'], ['How quickly should I reply?', 'Set a response expectation you can genuinely meet. A useful acknowledgement and a reliable follow-up are better than an unrealistic promise.']], date: '2026-10-06', landing: ['/services/whatsapp-systems', 'WhatsApp systems'], related: ['website-vs-whatsapp', 'how-to-follow-up-customer-enquiry'] }),
  guide({ slug: 'do-i-need-website-instagram-whatsapp', title: 'Do I need a website if I already have Instagram and WhatsApp?', description: 'Why a website can complement Instagram and WhatsApp by giving customers a stable, searchable place for essential information.', answer: 'You may still benefit from a website even if Instagram and WhatsApp already bring enquiries. A website gives customers a stable place to understand your offer, find key information and take the next step, while Instagram and WhatsApp remain useful for discovery and conversation.', focus: 'The question is not which channel wins. It is whether customers can easily find accurate information and move from interest to a useful enquiry.', steps: [['Give each channel a job', 'Instagram is useful for current visual updates, examples of work and discovery. WhatsApp is useful for personal questions and arranging a next step. A website is useful for your core offer, services, location or service area, frequently asked questions and a contact path that does not disappear in a feed.\n\nWhen each channel has a clear role, you spend less time repeating basic information and customers have fewer reasons to abandon the search.'], ['Build the essential pages first', 'You do not need a large website to begin. Start with a clear home page, services or products, information customers need before contacting you, and a direct enquiry route. Use your own words and current photos where available.\n\nMake the site work on mobile, because many visitors will arrive from a social profile. Test the path from an Instagram bio link through the page to a contact action.'], ['Keep information consistent', 'Check that the name, hours, services, location details and contact route agree across the website, Instagram and WhatsApp profile. When something changes, update the stable website information first, then update social posts or highlights as needed.\n\nDo not rely on a pinned post for important details. Customers may see an older post, arrive through a search result or share a direct page with someone else.'], ['Connect, do not duplicate', 'Use Instagram to point people to useful pages and use the website to link back to current social updates where appropriate. A WhatsApp button on a service page can carry the subject of the enquiry into the conversation.\n\nThe result should be a simple journey: discover the business, understand the offer, then contact the right person with context.']], checklist: ['The website states the core offer clearly.', 'Key details match across channels.', 'The mobile contact journey has been tested.', 'Instagram links to a useful destination.'], faqs: [['Can I use a link-in-bio page instead of a website?', 'It can organise links, but it usually cannot explain your offer or answer customer questions as clearly as focused service pages.'], ['Will a website replace Instagram?', 'No. It can support Instagram by giving followers a dependable place to find deeper information and contact options.']], date: '2026-10-12', landing: ['/services/website-development', 'website development'], related: ['website-vs-whatsapp', 'how-to-stop-missing-whatsapp-enquiries'] }),
  guide({ slug: 'whatsapp-business-app-vs-api', title: 'WhatsApp Business app vs WhatsApp Business API: which does a small business need?', description: 'A practical comparison of the WhatsApp Business app and API-style integrations without pushing unnecessary complexity.', answer: 'Most small businesses should begin with the WhatsApp Business app when a small team can manage conversations directly. An API-based setup becomes worth considering when the business needs a shared inbox, connected workflows or approved message templates at a scale the app cannot comfortably support.', focus: 'Choose based on the way your team handles enquiries today and the operational problem you need to solve, not because a more complex setup sounds more advanced.', steps: [['Understand the app option', 'The WhatsApp Business app is designed for direct business conversations. It can support a business profile, quick replies, labels and basic organisation. For a solo owner or small team with manageable enquiry volume, these tools may be enough to keep conversations moving.\n\nThe app still needs a process. Decide who replies, how serious enquiries are recorded and how another person can cover when the usual contact is unavailable.'], ['Understand API-based workflows', 'API-based WhatsApp solutions are generally used through an approved provider or business platform. They can support shared inboxes, system connections, routing and templates within the platform rules. The exact capabilities, costs and approvals depend on the provider and your configuration.\n\nThis route requires more planning. Map the customer journey, data flow, permissions and handoff before committing to an integration.'], ['Choose from the actual need', 'Stay with the app if direct conversations are manageable, one or two people own replies and a simple tracker handles follow-up. Consider an API-based workflow if multiple people need one reliable view, conversations must connect to a CRM or booking process, or manual copying repeatedly causes mistakes.\n\nDo not use automation to send unwanted messages. Keep customer consent, message content and platform requirements in view when designing any workflow.'], ['Plan a safe transition', 'If you move beyond the app, document the current contact route and protect the customer experience during the change. Test routing, ownership, templates and human handoff before relying on the new process.\n\nReview whether the new setup makes work clearer. More features are only useful when they reduce a real operational problem.']], checklist: ['The current inbox and owners are understood.', 'The required integrations are documented.', 'Customer handoff remains clear.', 'Platform and provider requirements are checked.'], faqs: [['Is the API automatically better?', 'No. It is better only when the business has a real need for shared workflows or integration that the app cannot handle well.'], ['Can I connect WhatsApp to a CRM?', 'A suitable approved setup can connect conversation context and customer records, but the design should respect platform rules and your team’s process.']], date: '2026-10-18', landing: ['/services/whatsapp-systems', 'WhatsApp systems'], related: ['how-to-stop-missing-whatsapp-enquiries', 'what-is-crm'] }),
  guide({ slug: 'spreadsheet-vs-crm-small-business', title: 'Spreadsheet vs CRM: what does a small business actually need?', description: 'How to decide whether a shared spreadsheet is enough or a CRM will make customer follow-up easier to manage.', answer: 'A spreadsheet is often enough for a simple, low-volume process with one clear owner, while a CRM becomes useful when several people need shared customer context, reliable reminders or a consistent sales process. Choose the lightest tool that your team can keep accurate.', focus: 'The decision is about workflow complexity, not status. A well-maintained spreadsheet is better than an unused CRM, and a CRM is useful only when it makes the next action easier to see.', steps: [['Start with the workflow, not the tool', 'List the fields, decisions and handoffs involved from enquiry to completion. Note whether several people update the same information, whether customers contact you more than once and whether you need to see a history of conversations.\n\nIf the process is simple and stable, a shared spreadsheet may be appropriate. If it regularly creates duplicate versions, missed actions or unclear ownership, the process may have outgrown it.'], ['Know where spreadsheets work well', 'A spreadsheet can be practical for a short lead list, a single service line or a small team that uses the same simple stages. Use clear columns, a shared location, basic access controls and a regular review.\n\nIts limitations appear when records need linked activities, permissions, automatic reminders, detailed histories or dependable reporting. Avoid solving each limitation with another disconnected sheet.'], ['Know what a CRM adds', 'A CRM can centralise contacts, activities, notes, ownership and pipeline stages. It can make the next action visible and reduce the need to search across messages and files. These benefits depend on agreed data and daily use.\n\nStart with a minimal configuration. Import only clean, relevant data and train the team on the exact actions they need to perform.'], ['Make a reversible decision', 'Pilot the process with a small group or one service line. Check whether updates are faster, handoffs are clearer and important follow-ups are less likely to be missed. Keep the first rollout focused, then expand when the team sees a genuine benefit.\n\nA good system can evolve. Do not lock the business into elaborate fields, reports or automation before the basics are working.']], checklist: ['The current workflow is mapped.', 'The shared sheet has a clear owner.', 'CRM needs are tied to real handoffs.', 'The first rollout is limited and reviewed.'], faqs: [['When should I stop using a spreadsheet?', 'Consider a CRM when collaboration, follow-up, history or permissions are consistently difficult to manage with the sheet.'], ['Will a CRM fix poor follow-up?', 'It can make ownership and reminders clearer, but the team still needs agreed response habits and regular review.']], date: '2026-10-24', landing: ['/services/crm-systems', 'CRM systems'], related: ['what-is-crm', 'improve-lead-management'] }),
  guide({ slug: 'how-to-follow-up-customer-enquiry', title: 'How do I follow up a customer enquiry?', description: 'A respectful follow-up process with simple message examples that help a small business move an enquiry forward.', answer: 'Follow up a customer enquiry by referring to the specific request, offering one clear next step and making it easy for the customer to reply. Be helpful rather than persistent: if the customer is not ready, leave the door open and record when, or whether, a future follow-up makes sense.', focus: 'A good follow-up is a continuation of a useful conversation, not a generic chase. Timing and wording should match what the customer asked for and what you genuinely have to offer.', steps: [['Record the agreed next step', 'After the first conversation, write down what was discussed, who owes the next action and when it should happen. A customer may be waiting for a quote, a call, photos, availability or internal approval. Your record should make that visible.\n\nAvoid following up just because a fixed number of days passed. Follow up because there is a relevant next step or because you promised to return with information.'], ['Write a specific, low-pressure message', 'Use the customer’s name, mention the service or request and give a simple choice. For example: “Hi [Name], I’m following up on your enquiry about [service]. Do you have any questions about the options we discussed, or would you like me to suggest a suitable next step?”\n\nIf you sent a quote, try: “Hi [Name], I wanted to check whether you had a chance to review the quote for [service]. I’m happy to clarify any part of it or discuss the next step when it suits you.”'], ['Make the next action easy', 'Offer one useful action: reply with a detail, book a call, choose an option or tell you to follow up later. Do not send a long list of questions when one answer will move the conversation forward.\n\nFor an appointment-related enquiry, you might write: “Hi [Name], would you like me to check available times for [service], or is there anything you need before deciding?” Keep promises about availability and pricing accurate.'], ['Know when to stop', 'If there is no reply after a reasonable, relevant follow-up, send a polite closing message rather than repeated nudges. For example: “Hi [Name], I’ll close this enquiry for now so I do not keep bothering you. If you would like to continue with [service], just reply here and we can pick it up.”\n\nRecord the outcome. A clear closed status helps the team focus on active enquiries and prevents a future colleague from sending the same message again.']], checklist: ['The request and promised action are recorded.', 'The message names the specific service.', 'One clear next step is offered.', 'Unresponsive enquiries are closed respectfully.'], faqs: [['How many times should I follow up?', 'There is no universal number. Use the context of the request, your previous promise and the customer’s preference; avoid repeated generic messages.'], ['Should I follow up on WhatsApp?', 'If that is where the customer started the conversation and it is appropriate for your business, it can be a convenient channel. Keep the message relevant and easy to answer.']], date: '2026-10-30', landing: ['/services/lead-management', 'lead management services'], related: ['how-to-stop-missing-whatsapp-enquiries', 'improve-lead-management'] }),
];
export const faqs=[['What type of businesses does Axivy work with?','We work with small and growing businesses, particularly service-based businesses such as automotive, restaurants, cafés, cleaning, maintenance and other SMEs.'],['How much do your services cost?','Pricing depends on the scope and features you need — the Services page lists a starting price for each service as a general guide. We confirm the exact cost after understanding your specific requirements, with no hidden fees.'],['Can you connect our website with WhatsApp?','Yes. We can design customer journeys where website enquiries can move into WhatsApp conversations, lead management and follow-up workflows.'],['Can AI handle customer enquiries?','AI can handle suitable repetitive tasks such as FAQs, information collection and basic lead qualification. More complex conversations can be handed over to a person.'],['Do you work with businesses remotely?','Yes. Most digital projects can be planned, built and managed remotely. For businesses in Qatar, we can also structure solutions around local business workflows.'],['Can you connect our existing tools?','In many cases, yes. We first review the tools and workflow you already use, then determine what can be connected or automated.'],['Do you provide ongoing support?','Yes. Ongoing support, improvements, monitoring and automation maintenance can be arranged based on your business needs.'],['Can Axivy build a custom business system?','Yes. When existing tools are not enough, we can build custom web applications and internal systems around your specific workflow.'],['How do we get started?','Tell us about your business and the problem you want to solve. We’ll review the workflow and discuss a practical next step.']];
